import inspect
from artifact_tool import Workbook, SpreadsheetFile, Blob
for cls in (Workbook, SpreadsheetFile, Blob):
    print('\nCLASS', cls.__name__)
    print([x for x in dir(cls) if not x.startswith('_')])
    for name in ['import_xlsx','export_xlsx','load','render','recalculate','inspect']:
        if hasattr(cls,name):
            m=getattr(cls,name)
            try: print(name, inspect.signature(m), inspect.getdoc(m))
            except Exception as e: print(str(e))
